const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');
const fs = require('fs');
const path = require('path');
const os = require('os');
const QRCode = require('qrcode');

const PORT = process.env.PORT || 3000;
const STATE_FILE = path.join(__dirname, 'event_state.json');

// Initial Master Data
const INITIAL_USHERS = [
  { id: 'A1', code: 'A1', name: 'Usher A1', defaultZone: 'A', currentZone: 'A', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'A2', code: 'A2', name: 'Usher A2', defaultZone: 'A', currentZone: 'A', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'A3', code: 'A3', name: 'Usher A3', defaultZone: 'A', currentZone: 'A', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'B1', code: 'B1', name: 'Usher B1', defaultZone: 'B', currentZone: 'B', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'B2', code: 'B2', name: 'Usher B2', defaultZone: 'B', currentZone: 'B', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'B3', code: 'B3', name: 'Usher B3', defaultZone: 'B', currentZone: 'B', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'C1', code: 'C1', name: 'Usher C1', defaultZone: 'C', currentZone: 'C', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'C2', code: 'C2', name: 'Usher C2', defaultZone: 'C', currentZone: 'C', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'C3', code: 'C3', name: 'Usher C3', defaultZone: 'C', currentZone: 'C', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'D1', code: 'D1', name: 'Usher D1', defaultZone: 'D', currentZone: 'D', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'D2', code: 'D2', name: 'Usher D2', defaultZone: 'D', currentZone: 'D', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'D3', code: 'D3', name: 'Usher D3', defaultZone: 'D', currentZone: 'D', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'E1', code: 'E1', name: 'Usher E1', defaultZone: 'E', currentZone: 'E', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'E2', code: 'E2', name: 'Usher E2', defaultZone: 'E', currentZone: 'E', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'E3', code: 'E3', name: 'Usher E3', defaultZone: 'E', currentZone: 'E', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'F1', code: 'F1', name: 'Usher F1', defaultZone: 'F', currentZone: 'F', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'F2', code: 'F2', name: 'Usher F2', defaultZone: 'F', currentZone: 'F', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
  { id: 'F3', code: 'F3', name: 'Usher F3', defaultZone: 'F', currentZone: 'F', status: 'AVAILABLE', activeTable: null, pendingDispatch: null, assignedAt: null, assistNote: '', lastUpdated: Date.now() },
];

// Helper to load or initialize state
function loadState() {
  try {
    if (fs.existsSync(STATE_FILE)) {
      const data = fs.readFileSync(STATE_FILE, 'utf8');
      return JSON.parse(data);
    }
  } catch (err) {
    console.error('Error loading state file:', err);
  }
  return {
    ushers: JSON.parse(JSON.stringify(INITIAL_USHERS)),
    activityLog: [
      { id: 'init', type: 'system', message: 'Sistem Usher Control diinisialisasi.', time: new Date().toLocaleTimeString('id-ID') }
    ],
    completedEscortsCount: 0
  };
}

let appState = loadState();

function saveState() {
  try {
    fs.writeFileSync(STATE_FILE, JSON.stringify(appState, null, 2));
  } catch (err) {
    console.error('Error saving state file:', err);
  }
}

function addActivity(type, message) {
  const logItem = {
    id: Date.now() + '-' + Math.random().toString(36).substring(2, 6),
    type,
    message,
    time: new Date().toLocaleTimeString('id-ID')
  };
  appState.activityLog.unshift(logItem);
  if (appState.activityLog.length > 50) {
    appState.activityLog = appState.activityLog.slice(0, 50);
  }
  return logItem;
}

const app = express();
app.use(cors());
app.use(express.json());

// Serve static frontend files if built
const distPath = path.join(__dirname, 'dist');
if (fs.existsSync(distPath)) {
  app.use(express.static(distPath));
}

// Get Local IPv4 Address
function getLocalIp() {
  const interfaces = os.networkInterfaces();
  for (const name of Object.keys(interfaces)) {
    for (const iface of interfaces[name]) {
      if (iface.family === 'IPv4' && !iface.internal) {
        return iface.address;
      }
    }
  }
  return 'localhost';
}

// REST API
app.get('/api/state', (req, res) => {
  res.json(appState);
});

app.get('/api/info', async (req, res) => {
  const localIp = getLocalIp();
  const fullUrl = `http://${localIp}:${PORT}`;
  const qrDataUrl = await QRCode.toDataURL(fullUrl, { width: 260, margin: 2 });
  res.json({
    localIp,
    port: PORT,
    fullUrl,
    qrDataUrl
  });
});

app.post('/api/reset', (req, res) => {
  appState.ushers = JSON.parse(JSON.stringify(INITIAL_USHERS));
  addActivity('reset', 'Semua status usher direset ke AVAILABLE oleh Koordinator.');
  saveState();
  io.emit('state:updated', appState);
  res.json({ success: true, message: 'Event reset successfully', state: appState });
});

// Fallback for SPA routing
app.get('*', (req, res) => {
  if (fs.existsSync(path.join(distPath, 'index.html'))) {
    res.sendFile(path.join(distPath, 'index.html'));
  } else {
    res.send('Usher Control Backend is running. Please start the frontend with npm run dev or build with npm run build.');
  }
});

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: '*',
    methods: ['GET', 'POST']
  }
});

io.on('connection', (socket) => {
  // Send current state to newly connected client
  socket.emit('state:init', appState);

  // Usher updates their zone
  socket.on('usher:update_zone', ({ usherId, zone }) => {
    const usher = appState.ushers.find(u => u.id === usherId);
    if (usher) {
      const oldZone = usher.currentZone;
      usher.currentZone = zone;
      usher.lastUpdated = Date.now();
      addActivity('zone_change', `${usher.name} pindah posisi dari Zona ${oldZone} ke Zona ${zone}.`);
      saveState();
      io.emit('state:updated', appState);
    }
  });

  // Coordinator dispatches a table to an usher
  socket.on('dispatch:assign', ({ usherId, tableNumber, zone, area, note }) => {
    const usher = appState.ushers.find(u => u.id === usherId);
    if (!usher) return;

    // Rule: Usher who is ESCORTING cannot be given a new task
    if (usher.status === 'ESCORTING') {
      socket.emit('error:message', `Usher ${usher.name} sedang mengantar tamu (ESCORTING).`);
      return;
    }

    usher.pendingDispatch = {
      tableNumber,
      zone,
      area,
      note: note || '',
      assignedAt: Date.now()
    };
    usher.lastUpdated = Date.now();
    addActivity('dispatch', `Koordinator menugaskan Meja ${tableNumber} (Zona ${zone}) ke ${usher.name}.`);
    saveState();
    io.emit('state:updated', appState);
    io.emit('notification:dispatch', { usherId, tableNumber, zone, area });
  });

  // Usher accepts the dispatched task -> Status becomes ESCORTING
  socket.on('dispatch:accept', ({ usherId }) => {
    const usher = appState.ushers.find(u => u.id === usherId);
    if (usher && usher.pendingDispatch) {
      usher.activeTable = usher.pendingDispatch;
      usher.pendingDispatch = null;
      usher.status = 'ESCORTING';
      usher.lastUpdated = Date.now();
      addActivity('escort_start', `${usher.name} menerima tugas dan mengantar tamu ke Meja ${usher.activeTable.tableNumber}.`);
      saveState();
      io.emit('state:updated', appState);
    }
  });

  // Usher completes escort -> TAMU SUDAH DUDUK
  socket.on('dispatch:complete', ({ usherId, returnStatus = 'AVAILABLE' }) => {
    const usher = appState.ushers.find(u => u.id === usherId);
    if (usher) {
      const tableNum = usher.activeTable ? usher.activeTable.tableNumber : 'Meja';
      usher.status = returnStatus; // 'AVAILABLE' or 'RETURNING'
      usher.activeTable = null;
      usher.pendingDispatch = null;
      usher.lastUpdated = Date.now();
      appState.completedEscortsCount = (appState.completedEscortsCount || 0) + 1;
      addActivity('escort_complete', `${usher.name} selesai mengantar tamu ke Meja ${tableNum}. Status: ${returnStatus}.`);
      saveState();
      io.emit('state:updated', appState);
    }
  });

  // Usher updates status directly (e.g. Returning to Available, or Manual toggle)
  socket.on('usher:update_status', ({ usherId, status, note }) => {
    const usher = appState.ushers.find(u => u.id === usherId);
    if (usher) {
      const prevStatus = usher.status;
      usher.status = status;
      if (note !== undefined) usher.assistNote = note;
      if (status === 'AVAILABLE') {
        usher.activeTable = null;
        usher.pendingDispatch = null;
        usher.assistNote = '';
      }
      usher.lastUpdated = Date.now();
      addActivity('status_change', `${usher.name} mengubah status dari ${prevStatus} menjadi ${status}.`);
      saveState();
      io.emit('state:updated', appState);
    }
  });

  // Usher requests assistance (ASSIST)
  socket.on('usher:request_assist', ({ usherId, note }) => {
    const usher = appState.ushers.find(u => u.id === usherId);
    if (usher) {
      usher.status = 'ASSIST';
      usher.assistNote = note || 'Membutuhkan bantuan koordinator di lokasi.';
      usher.lastUpdated = Date.now();
      addActivity('assist_request', `[PERHATIAN] ${usher.name} (Zona ${usher.currentZone}) meminta BANTUAN: ${usher.assistNote}`);
      saveState();
      io.emit('state:updated', appState);
      io.emit('notification:assist', { usherId, name: usher.name, zone: usher.currentZone, note: usher.assistNote });
    }
  });

  // Coordinator resolves assist
  socket.on('usher:resolve_assist', ({ usherId, newStatus = 'AVAILABLE' }) => {
    const usher = appState.ushers.find(u => u.id === usherId);
    if (usher) {
      usher.status = newStatus;
      usher.assistNote = '';
      usher.lastUpdated = Date.now();
      addActivity('assist_resolved', `Bantuan untuk ${usher.name} telah ditangani. Status kembali ${newStatus}.`);
      saveState();
      io.emit('state:updated', appState);
    }
  });

  // Event reset
  socket.on('event:reset', () => {
    appState.ushers = JSON.parse(JSON.stringify(INITIAL_USHERS));
    addActivity('reset', 'Seluruh status usher direset ke AVAILABLE.');
    saveState();
    io.emit('state:updated', appState);
  });
});

server.listen(PORT, '0.0.0.0', () => {
  const localIp = getLocalIp();
  console.log(`=================================================`);
  console.log(`🚀 Usher Control Event Server is running!`);
  console.log(`💻 Local access : http://localhost:${PORT}`);
  console.log(`📱 Mobile/LAN   : http://${localIp}:${PORT}`);
  console.log(`=================================================`);
});

