:root {
  --font-main: 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* Colors */
  --bg-primary: #0b0f19;
  --bg-secondary: #111827;
  --bg-card: rgba(17, 24, 39, 0.85);
  --bg-card-hover: rgba(31, 41, 55, 0.9);
  --border-color: rgba(255, 255, 255, 0.08);
  --border-focus: #3b82f6;

  --text-primary: #f9fafb;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;

  /* Status Colors */
  --status-available: #10b981;
  --status-available-glow: rgba(16, 185, 129, 0.35);
  --status-escorting: #3b82f6;
  --status-escorting-glow: rgba(59, 130, 246, 0.35);
  --status-returning: #f59e0b;
  --status-returning-glow: rgba(245, 158, 11, 0.35);
  --status-assist: #ef4444;
