import React, { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import { io } from 'socket.io-client';
import { INITIAL_USHERS, TABLES, ZONES } from '../data/eventData';

const AppContext = createContext(null);

// Web Audio API Sound generator for crystal-clear offline audio cues
function playBeep(type = 'dispatch') {
  try {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    const ctx = new AudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    if (type === 'dispatch') {
      // Pleasant high double ping for new task
      osc.type = 'sine';
      osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
      osc.frequency.setValueAtTime(880, ctx.currentTime + 0.12); // A5
      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.4);
    } else if (type === 'assist') {
      // Urgent warning beep for assist
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(440, ctx.currentTime);
      osc.frequency.setValueAtTime(330, ctx.currentTime + 0.15);
      osc.frequency.setValueAtTime(440, ctx.currentTime + 0.3);
      gain.gain.setValueAtTime(0.4, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.5);
    } else if (type === 'complete') {
      // Gentle cheerful chime for success
      osc.type = 'sine';
      osc.frequency.setValueAtTime(523.25, ctx.currentTime); // C5
      osc.frequency.setValueAtTime(659.25, ctx.currentTime + 0.1); // E5
      osc.frequency.setValueAtTime(783.99, ctx.currentTime + 0.2); // G5
      gain.gain.setValueAtTime(0.25, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.45);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.45);
    }
  } catch (e) {
    console.warn('Audio playback not permitted yet (user interaction required):', e);
  }
}

export function AppProvider({ children }) {
  const [ushers, setUshers] = useState(INITIAL_USHERS);
  const [activityLog, setActivityLog] = useState([]);
  const [completedEscortsCount, setCompletedEscortsCount] = useState(0);
  const [isConnected, setIsConnected] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState('connecting'); // 'connected' | 'connecting' | 'offline'

  // User Auth & Session
  const [currentRole, setCurrentRole] = useState(() => localStorage.getItem('usher_role') || null); // 'coordinator' | 'usher' | null
  const [activeUsherId, setActiveUsherId] = useState(() => localStorage.getItem('usher_active_id') || null);
  const [isCoordAuthenticated, setIsCoordAuthenticated] = useState(() => localStorage.getItem('usher_coord_auth') === 'true');

  const socketRef = useRef(null);

  // Initialize Socket.io connection
  useEffect(() => {
    // Connect to host (either direct or proxied)
    const socketUrl = window.location.origin;
    const socket = io(socketUrl, {
      reconnectionAttempts: 50,
      reconnectionDelay: 1000,
      timeout: 10000,
    });

    socketRef.current = socket;

    socket.on('connect', () => {
      setIsConnected(true);
      setConnectionStatus('connected');
    });

    socket.on('disconnect', () => {
      setIsConnected(false);
      setConnectionStatus('offline');
    });

    socket.on('connect_error', () => {
      setIsConnected(false);
      setConnectionStatus('offline');
    });

    socket.on('state:init', (state) => {
      if (state && state.ushers) {
        setUshers(state.ushers);
        if (state.activityLog) setActivityLog(state.activityLog);
        if (state.completedEscortsCount !== undefined) setCompletedEscortsCount(state.completedEscortsCount);
      }
    });

    socket.on('state:updated', (state) => {
      if (state && state.ushers) {
        setUshers(state.ushers);
        if (state.activityLog) setActivityLog(state.activityLog);
        if (state.completedEscortsCount !== undefined) setCompletedEscortsCount(state.completedEscortsCount);
      }
    });

    socket.on('notification:dispatch', ({ usherId, tableNumber, zone }) => {
      // If current active usher is this usher, play sound & vibrate
      if (localStorage.getItem('usher_active_id') === usherId) {
        playBeep('dispatch');
        if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      }
    });

    socket.on('notification:assist', ({ usherId, name, zone, note }) => {
      // Coordinator alert
      playBeep('assist');
      if (navigator.vibrate) navigator.vibrate([300, 200, 300, 200, 300]);
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  // Sync to local storage
  const setRole = useCallback((role) => {
    setCurrentRole(role);
    if (role) {
      localStorage.setItem('usher_role', role);
    } else {
      localStorage.removeItem('usher_role');
    }
  }, []);

  const setUsherId = useCallback((id) => {
    setActiveUsherId(id);
    if (id) {
      localStorage.setItem('usher_active_id', id);
    } else {
      localStorage.removeItem('usher_active_id');
    }
  }, []);

  const setCoordAuth = useCallback((authed) => {
    setIsCoordAuthenticated(authed);
    if (authed) {
      localStorage.setItem('usher_coord_auth', 'true');
    } else {
      localStorage.removeItem('usher_coord_auth');
    }
  }, []);

  // Realtime Actions
  const updateUsherZone = useCallback((usherId, zone) => {
    if (socketRef.current) {
      socketRef.current.emit('usher:update_zone', { usherId, zone });
    }
  }, []);

  const updateUsherStatus = useCallback((usherId, status, note) => {
    if (socketRef.current) {
      socketRef.current.emit('usher:update_status', { usherId, status, note });
    }
  }, []);

  const dispatchAssign = useCallback((usherId, tableNumber, zone, area, note = '') => {
    if (socketRef.current) {
      socketRef.current.emit('dispatch:assign', { usherId, tableNumber, zone, area, note });
    }
  }, []);

  const dispatchAccept = useCallback((usherId) => {
    if (socketRef.current) {
      socketRef.current.emit('dispatch:accept', { usherId });
    }
  }, []);

  const dispatchComplete = useCallback((usherId, returnStatus = 'AVAILABLE') => {
    playBeep('complete');
    if (socketRef.current) {
      socketRef.current.emit('dispatch:complete', { usherId, returnStatus });
    }
  }, []);

  const requestAssist = useCallback((usherId, note = '') => {
    playBeep('assist');
    if (socketRef.current) {
      socketRef.current.emit('usher:request_assist', { usherId, note });
    }
  }, []);

  const resolveAssist = useCallback((usherId, newStatus = 'AVAILABLE') => {
    if (socketRef.current) {
      socketRef.current.emit('usher:resolve_assist', { usherId, newStatus });
    }
  }, []);

  const resetEvent = useCallback(() => {
    if (socketRef.current) {
      socketRef.current.emit('event:reset');
    }
  }, []);

  const getUsherById = useCallback((id) => {
    return ushers.find((u) => u.id === id) || null;
  }, [ushers]);

  const getTableInfo = useCallback((tableNumber) => {
    const num = parseInt(tableNumber, 10);
    return TABLES.find((t) => t.number === num) || null;
  }, []);

  const value = {
    ushers,
    activityLog,
    completedEscortsCount,
    isConnected,
    connectionStatus,
    currentRole,
    setRole,
    activeUsherId,
    setUsherId,
    isCoordAuthenticated,
    setCoordAuth,
    getUsherById,
    getTableInfo,
    updateUsherZone,
    updateUsherStatus,
    dispatchAssign,
    dispatchAccept,
    dispatchComplete,
    requestAssist,
    resolveAssist,
    resetEvent,
    playBeep
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

export function useApp() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
}

