import React, { useState, useMemo } from 'react';
import { useApp } from '../context/AppContext';
import { TABLES, ZONES } from '../data/eventData';
import { Search, Send, UserCheck, AlertCircle, X, Sparkles, CheckCircle2, Footprints, ShieldAlert } from 'lucide-react';

export default function DispatchModal({ initialTable = '', onClose }) {
  const { ushers, dispatchAssign } = useApp();
  const [tableInput, setTableInput] = useState(initialTable.toString());
  const [selectedUsherId, setSelectedUsherId] = useState(null);
  const [allowBackup, setAllowBackup] = useState(false);
  const [customNote, setCustomNote] = useState('');
  const [dispatchSuccess, setDispatchSuccess] = useState(false);

  // Look up table info
  const tableNum = parseInt(tableInput, 10);
  const tableInfo = useMemo(() => {
    if (!tableNum) return null;
    return TABLES.find(t => t.number === tableNum) || null;
  }, [tableNum]);

  // Zone info for this table
  const zoneInfo = useMemo(() => {
    if (!tableInfo) return null;
    return ZONES.find(z => z.id === tableInfo.zone) || null;
  }, [tableInfo]);

  // Available ushers for this table
  const zoneUshers = useMemo(() => {
    if (!zoneInfo) return [];
    // Ushers currently in this zone or whose default zone is this zone
    return ushers.filter(u => u.currentZone === zoneInfo.id);
  }, [ushers, zoneInfo]);

  // Other available ushers from other zones (for backup)
  const otherAvailableUshers = useMemo(() => {
    if (!zoneInfo) return [];
    return ushers.filter(u => u.currentZone !== zoneInfo.id && u.status === 'AVAILABLE');
  }, [ushers, zoneInfo]);

  const handleNumpadClick = (val) => {
    if (tableInput.length < 3) {
      setTableInput(prev => prev + val);
    }
  };

  const handleClear = () => {
    setTableInput('');
    setSelectedUsherId(null);
  };

  const handleBackspace = () => {
    setTableInput(prev => prev.slice(0, -1));
    setSelectedUsherId(null);
  };

  const handleDispatch = () => {
    if (!selectedUsherId || !tableInfo) return;
    dispatchAssign(selectedUsherId, tableInfo.number, tableInfo.zone, tableInfo.area, customNote);
    setDispatchSuccess(true);
    setTimeout(() => {
      onClose();
    }, 1200);
  };

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.85)',
      backdropFilter: 'blur(8px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 100,
      padding: '16px'
    }}>
      <div className="glass-panel animate-pop" style={{
        width: '100%',
        maxWidth: '500px',
        maxHeight: '92vh',
        overflowY: 'auto',
        padding: '20px',
        backgroundColor: '#0f172a',
        border: '1px solid #334155'
      }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <div style={{
              width: '32px',
              height: '32px',
              borderRadius: '8px',
              backgroundColor: 'rgba(59, 130, 246, 0.2)',
              color: '#60a5fa',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}>
              <Send size={18} />
            </div>
            <div>
              <h3 style={{ fontSize: '18px', fontWeight: 800, color: '#f8fafc' }}>
                Dispatch Meja → Usher
              </h3>
              <div style={{ fontSize: '11px', color: '#94a3b8' }}>
                Lookup nomor meja (1–102) & tugaskan usher yang siap
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            style={{ background: '#1e293b', color: '#94a3b8', border: 'none', borderRadius: '8px', padding: '6px' }}
          >
            <X size={18} />
          </button>
        </div>

        {dispatchSuccess ? (
          <div style={{ textAlign: 'center', padding: '36px 16px' }} className="animate-pop">
            <div style={{
              width: '64px',
              height: '64px',
              borderRadius: '50%',
              backgroundColor: 'rgba(16, 185, 129, 0.2)',
              color: '#34d399',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              margin: '0 auto 16px'
            }}>
              <CheckCircle2 size={36} />
            </div>
            <h3 style={{ fontSize: '20px', fontWeight: 800, color: '#f8fafc', marginBottom: '6px' }}>
              Tugas Berhasil Dikirim!
            </h3>
            <p style={{ fontSize: '14px', color: '#a7f3d0' }}>
              Meja {tableInfo?.number} (Zona {tableInfo?.zone}) telah dikirim ke usher.
            </p>
          </div>
        ) : (
          <>
            {/* Table Number Display & Input */}
            <div style={{
              backgroundColor: '#1e293b',
              border: '2px solid #3b82f6',
