                  <span>PILIH USHER DI {zoneInfo.name.toUpperCase()} ({zoneInfo.area}):</span>
                  <span style={{ fontSize: '11px', color: '#60a5fa' }}>
                    {zoneUshers.filter(u => u.status === 'AVAILABLE').length} Siap
                  </span>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>
                  {zoneUshers.map((usher) => {
                    const isAvail = usher.status === 'AVAILABLE';
                    const isSelected = selectedUsherId === usher.id;
                    return (
                      <button
                        key={usher.id}
                        disabled={!isAvail}
                        onClick={() => setSelectedUsherId(usher.id)}
                        style={{
                          backgroundColor: isSelected
                            ? '#3b82f6'
                            : isAvail
                            ? 'rgba(16, 185, 129, 0.12)'
                            : '#1e293b',
                          border: isSelected
                            ? '2px solid #93c5fd'
                            : isAvail
                            ? '1px solid rgba(16, 185, 129, 0.4)'
                            : '1px solid #334155',
                          borderRadius: '12px',
                          padding: '10px 6px',
                          color: !isAvail ? '#64748b' : isSelected ? '#ffffff' : '#f8fafc',
                          opacity: !isAvail ? 0.5 : 1,
                          cursor: !isAvail ? 'not-allowed' : 'pointer',
                          display: 'flex',
                          flexDirection: 'column',
                          alignItems: 'center',
                          gap: '4px'
                        }}
                      >
                        <div style={{ fontSize: '16px', fontWeight: 800 }}>
                          {usher.code}
                        </div>
                        <div style={{
                          fontSize: '10px',
                          fontWeight: 700,
                          color: isSelected ? '#ffffff' : isAvail ? '#34d399' : '#94a3b8'
                        }}>
                          {isAvail ? 'READY' : usher.status}
                        </div>
                      </button>
                    );
                  })}
                </div>

                {/* If all ushers in zone are busy, offer backup toggle (Section 10) */}
                {zoneUshers.every(u => u.status !== 'AVAILABLE') && (
                  <div style={{
                    marginTop: '10px',
                    padding: '10px 12px',
                    backgroundColor: 'rgba(245, 158, 11, 0.12)',
                    border: '1px solid rgba(245, 158, 11, 0.3)',
                    borderRadius: '10px',
                    fontSize: '12px',
                    color: '#fbbf24'
                  }}>
                    <div style={{ fontWeight: 700, marginBottom: '4px' }}>
                      Semua usher di {zoneInfo.name} sedang sibuk!
                    </div>
                    <div>
                      Gunakan bantuan/backup dari zona lain:
                    </div>
                    <button
                      type="button"
                      onClick={() => setAllowBackup(true)}
                      style={{
                        marginTop: '6px',
                        backgroundColor: '#f59e0b',
                        color: '#000',
                        fontSize: '11px',
                        fontWeight: 800,
                        padding: '4px 10px',
                        borderRadius: '6px'
                      }}
                    >
                      TAMPILKAN USHER BACKUP ZONA LAIN
                    </button>
                  </div>
                )}

                {/* Backup Ushers list */}
                {allowBackup && otherAvailableUshers.length > 0 && (
                  <div style={{ marginTop: '14px' }} className="animate-slide-up">
                    <div style={{ fontSize: '12px', color: '#f59e0b', fontWeight: 700, marginBottom: '6px' }}>
                      USHER TERSEDIA DARI ZONA LAIN (BACKUP):
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>
                      {otherAvailableUshers.map((usher) => {
                        const isSelected = selectedUsherId === usher.id;
                        return (
                          <button
                            key={usher.id}
                            onClick={() => setSelectedUsherId(usher.id)}
                            style={{
                              backgroundColor: isSelected ? '#f59e0b' : '#1e293b',
                              border: isSelected ? '2px solid #ffffff' : '1px solid #f59e0b',
                              color: isSelected ? '#000000' : '#fde68a',
                              borderRadius: '10px',
                              padding: '8px 6px',
                              fontSize: '13px',
                              fontWeight: 700
                            }}
                          >
                            <div>{usher.code}</div>
                            <div style={{ fontSize: '10px' }}>Zona {usher.currentZone}</div>
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Action Submit Button */}
            <button
              disabled={!selectedUsherId || !tableInfo}
              onClick={handleDispatch}
              style={{
                width: '100%',
                backgroundColor: !selectedUsherId || !tableInfo ? '#334155' : '#3b82f6',
                color: !selectedUsherId || !tableInfo ? '#94a3b8' : '#ffffff',
                borderRadius: '14px',
                padding: '16px',
                fontSize: '16px',
                fontWeight: 800,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px',
                boxShadow: selectedUsherId && tableInfo ? '0 6px 20px rgba(59, 130, 246, 0.4)' : 'none',
                cursor: !selectedUsherId || !tableInfo ? 'not-allowed' : 'pointer'
              }}
            >
              <Send size={18} />
              <span>
                {selectedUsherId && tableInfo
                  ? `TUGASKAN MEJA ${tableInfo.number} KE USHER ${selectedUsherId}`
                  : 'PILIH MEJA & USHER TERLEBIH DAHULU'}
              </span>
            </button>
          </>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { useApp } from '../context/AppContext';
import { ZONES, TABLES } from '../data/eventData';
import { Users, CheckCircle2, Footprints, AlertTriangle } from 'lucide-react';

export default function BallroomMap({ onSelectTable }) {
  const { ushers } = useApp();

  const getZoneStats = (zoneId) => {
    const zoneUshers = ushers.filter((u) => u.currentZone === zoneId);
    const available = zoneUshers.filter((u) => u.status === 'AVAILABLE').length;
    const escorting = zoneUshers.filter((u) => u.status === 'ESCORTING').length;
    const assist = zoneUshers.filter((u) => u.status === 'ASSIST').length;
    return { total: zoneUshers.length, available, escorting, assist, ushers: zoneUshers };
  };

  const leftZones = ['A', 'B', 'C'];
  const rightZones = ['D', 'E', 'F'];

  const renderZoneBlock = (zoneId) => {
    const zone = ZONES.find((z) => z.id === zoneId);
    const stats = getZoneStats(zoneId);
    const zoneTables = TABLES.filter((t) => t.zone === zoneId);

    return (
      <div
        key={zoneId}
        style={{
          backgroundColor: '#111827',
          border: `2px solid ${stats.assist > 0 ? '#ef4444' : zone.border}`,
          borderRadius: '14px',
          padding: '12px',
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
          boxShadow: stats.assist > 0 ? '0 0 15px rgba(239, 68, 68, 0.4)' : 'none'
        }}
      >
        {/* Zone Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <span style={{
              width: '10px',
              height: '10px',
              borderRadius: '50%',
              backgroundColor: zone.color
            }} />
            <span style={{ fontSize: '14px', fontWeight: 800, color: '#f8fafc' }}>
              {zone.name}
            </span>
            <span style={{ fontSize: '10px', color: '#94a3b8' }}>
              ({zone.area})
            </span>
          </div>

          <div style={{ display: 'flex', gap: '4px', fontSize: '10px', fontWeight: 700 }}>
            <span style={{ color: '#34d399', backgroundColor: 'rgba(16, 185, 129, 0.15)', padding: '2px 6px', borderRadius: '6px' }}>
              {stats.available} Ready
            </span>
            {stats.escorting > 0 && (
              <span style={{ color: '#60a5fa', backgroundColor: 'rgba(59, 130, 246, 0.15)', padding: '2px 6px', borderRadius: '6px' }}>
                {stats.escorting} Escort
              </span>
            )}
            {stats.assist > 0 && (
              <span style={{ color: '#f87171', backgroundColor: 'rgba(239, 68, 68, 0.2)', padding: '2px 6px', borderRadius: '6px' }} className="glow-red">
                {stats.assist} Assist!
              </span>
            )}
          </div>
        </div>

        {/* Ushers in this zone */}
        <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
          {stats.ushers.map((u) => {
            const isAvail = u.status === 'AVAILABLE';
            const isEscort = u.status === 'ESCORTING';
            const isAssist = u.status === 'ASSIST';
            return (
              <div
                key={u.id}
                style={{
                  fontSize: '11px',
                  fontWeight: 700,
                  padding: '3px 8px',
                  borderRadius: '6px',
                  backgroundColor: isAssist
                    ? 'rgba(239, 68, 68, 0.25)'
                    : isEscort
                    ? 'rgba(59, 130, 246, 0.25)'
                    : 'rgba(16, 185, 129, 0.15)',
                  color: isAssist ? '#f87171' : isEscort ? '#60a5fa' : '#34d399',
                  border: isAssist ? '1px solid #ef4444' : '1px solid transparent',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px'
                }}
              >
                <span>{u.code}</span>
                {isEscort && u.activeTable && (
                  <span style={{ color: '#93c5fd', fontSize: '9px' }}>→ M{u.activeTable.tableNumber}</span>
                )}
              </div>
            );
          })}
        </div>

        {/* Quick Table Chips */}
        <div style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: '4px',
          maxHeight: '68px',
          overflowY: 'auto',
          paddingTop: '4px',
          borderTop: '1px solid rgba(255, 255, 255, 0.05)'
        }}>
          {zoneTables.map((t) => (
            <button
              key={t.number}
              onClick={() => onSelectTable(t.number)}
              title={`Klik untuk dispatch Meja ${t.number}`}
              style={{
                backgroundColor: '#1f2937',
                border: '1px solid #374151',
                borderRadius: '4px',
                color: '#e2e8f0',
                fontSize: '10px',
                fontWeight: 600,
                padding: '2px 5px'
              }}
            >
              M{t.number}
            </button>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="glass-panel" style={{ padding: '16px', marginBottom: '20px' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '12px' }}>
        <div>
          <h3 style={{ fontSize: '15px', fontWeight: 800, color: '#f8fafc' }}>
            Denah & Distribusi Ballroom
          </h3>
          <p style={{ fontSize: '11px', color: '#94a3b8' }}>
            Tata letak 6 Zona & 80 Meja (Klik meja untuk dispatch cepat)
          </p>
        </div>
        <div style={{
          fontSize: '11px',
          color: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.1)',
          padding: '4px 10px',
          borderRadius: '12px',
          fontWeight: 700
        }}>
          STAGE / PANGGUNG ⬆️
        </div>
      </div>

      {/* 2 Column Layout: Kiri (A, B, C) and Kanan (D, E, F) */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
        gap: '12px'
      }}>
        {/* Sisi Kiri Ballroom */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <div style={{ fontSize: '11px', fontWeight: 800, color: '#94a3b8', letterSpacing: '0.5px' }}>
            SISI KIRI BALLROOM (GANJIL)
          </div>
          {leftZones.map(renderZoneBlock)}
        </div>

        {/* Sisi Kanan Ballroom */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <div style={{ fontSize: '11px', fontWeight: 800, color: '#94a3b8', letterSpacing: '0.5px' }}>
            SISI KANAN BALLROOM (GENAP)
          </div>
          {rightZones.map(renderZoneBlock)}
        </div>
      </div>
    </div>
  );
}

