import React, { useState, useEffect } from 'react';
import { X, Copy, Check, Smartphone, ExternalLink } from 'lucide-react';

export default function QrModal({ onClose }) {
  const [info, setInfo] = useState(null);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    fetch('/api/info')
      .then(res => res.json())
      .then(data => setInfo(data))
      .catch(err => console.error('Failed to fetch server info:', err));
  }, []);

  const fallbackUrl = window.location.origin;
  const targetUrl = info?.fullUrl || fallbackUrl;

  const handleCopy = () => {
    navigator.clipboard.writeText(targetUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.85)',
      backdropFilter: 'blur(8px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 100,
      padding: '16px'
    }}>
      <div className="glass-panel animate-pop" style={{
        width: '100%',
        maxWidth: '380px',
        padding: '24px',
        backgroundColor: '#0f172a',
        border: '1px solid #334155',
        textAlign: 'center'
      }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <Smartphone size={20} color="#38bdf8" />
            <h3 style={{ fontSize: '18px', fontWeight: 800, color: '#f8fafc' }}>
              Scan untuk Akses HP
            </h3>
          </div>
          <button
            onClick={onClose}
            style={{ background: '#1e293b', color: '#94a3b8', border: 'none', borderRadius: '8px', padding: '6px' }}
          >
            <X size={18} />
          </button>
        </div>

        <p style={{ fontSize: '12px', color: '#94a3b8', marginBottom: '16px' }}>
          Pastikan HP terhubung ke Wi-Fi / jaringan yang sama, lalu scan QR Code ini dengan kamera HP:
        </p>

        {/* QR Code display */}
        <div style={{
          backgroundColor: '#ffffff',
          borderRadius: '16px',
          padding: '12px',
          display: 'inline-block',
          boxShadow: '0 8px 24px rgba(0, 0, 0, 0.4)',
          marginBottom: '16px'
        }}>
          {info?.qrDataUrl ? (
            <img
              src={info.qrDataUrl}
              alt="Scan QR Code"
              style={{ width: '220px', height: '220px', display: 'block' }}
            />
          ) : (
            <div style={{ width: '220px', height: '220px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#000' }}>
              Membuat QR Code...
            </div>
          )}
        </div>

        {/* Direct URL display */}
        <div style={{
          backgroundColor: '#1e293b',
          border: '1px solid #334155',
          borderRadius: '10px',
          padding: '8px 12px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          marginBottom: '14px'
        }}>
          <span style={{ fontSize: '13px', color: '#38bdf8', fontWeight: 700, wordBreak: 'break-all' }}>
            {targetUrl}
          </span>
          <button
            onClick={handleCopy}
            title="Salin Link"
            style={{
              background: '#334155',
              border: 'none',
              borderRadius: '6px',
              padding: '6px 8px',
              color: copied ? '#34d399' : '#ffffff',
              display: 'flex',
              alignItems: 'center',
              gap: '4px',
              fontSize: '11px',
              fontWeight: 700
            }}
          >
            {copied ? <Check size={14} /> : <Copy size={14} />}
            <span>{copied ? 'Tersalin' : 'Salin'}</span>
          </button>
        </div>

        <button
          onClick={onClose}
          style={{
            width: '100%',
            backgroundColor: '#3b82f6',
            color: '#ffffff',
            borderRadius: '10px',
            padding: '12px',
            fontSize: '14px',
            fontWeight: 700
          }}
        >
          Tutup
        </button>
      </div>
    </div>
  );
}

