import React, { useState } from 'react';
import { useApp } from './context/AppContext';
import Header from './components/Header';
import LandingView from './components/LandingView';
import UsherSelectView from './components/UsherSelectView';
import UsherDashboard from './components/UsherDashboard';
import CoordinatorDashboard from './components/CoordinatorDashboard';
import DispatchModal from './components/DispatchModal';
import AssistModal from './components/AssistModal';
import QrModal from './components/QrModal';
import ResetConfirmModal from './components/ResetConfirmModal';

export default function App() {
  const { currentRole, setRole, activeUsherId, isCoordAuthenticated } = useApp();

  const [isChoosingUsher, setIsChoosingUsher] = useState(false);
  const [showQrModal, setShowQrModal] = useState(false);
  const [showResetModal, setShowResetModal] = useState(false);
  const [dispatchModalData, setDispatchModalData] = useState(null); // { tableNum: '', usherId: '' } or null
  const [showAssistModal, setShowAssistModal] = useState(false);

  // Handle open dispatch modal
  const handleOpenDispatch = (tableNum = '', usherId = null) => {
    setDispatchModalData({ tableNum, usherId });
  };

  const handleCloseDispatch = () => {
    setDispatchModalData(null);
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      {/* Top sticky Navbar */}
      <Header
        onOpenQr={() => setShowQrModal(true)}
        onOpenReset={() => setShowResetModal(true)}
      />

      {/* Main Content Router based on Role & State */}
      <main style={{ flex: 1 }}>
        {/* If no role is selected */}
        {!currentRole && (
          <>
            {isChoosingUsher ? (
              <UsherSelectView onBack={() => setIsChoosingUsher(false)} />
            ) : (
              <LandingView
                onSelectUsherMode={() => setIsChoosingUsher(true)}
                onOpenQr={() => setShowQrModal(true)}
              />
            )}
          </>
        )}

        {/* If Usher Role is selected */}
        {currentRole === 'usher' && (
          <>
            {activeUsherId ? (
              <UsherDashboard onOpenAssistModal={() => setShowAssistModal(true)} />
            ) : (
              <UsherSelectView onBack={() => setRole(null)} />
            )}
          </>
        )}

        {/* If Coordinator Role is selected */}
        {currentRole === 'coordinator' && isCoordAuthenticated && (
          <CoordinatorDashboard
            onOpenDispatch={handleOpenDispatch}
            onOpenReset={() => setShowResetModal(true)}
          />
        )}
      </main>

      {/* Global Interactive Modals */}
      {showQrModal && (
        <QrModal onClose={() => setShowQrModal(false)} />
      )}

      {showResetModal && (
        <ResetConfirmModal onClose={() => setShowResetModal(false)} />
      )}

      {dispatchModalData && (
        <DispatchModal
          initialTable={dispatchModalData.tableNum}
          initialUsherId={dispatchModalData.usherId}
          onClose={handleCloseDispatch}
        />
      )}

      {showAssistModal && (
        <AssistModal onClose={() => setShowAssistModal(false)} />
      )}
    </div>
  );
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { AppProvider } from './context/AppContext';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <AppProvider>
      <App />
    </AppProvider>
  </React.StrictMode>
);

