const { io } = require('socket.io-client');
const http = require('http');

const SERVER_URL = 'http://localhost:3000';

function wait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function runTests() {
  console.log('🧪 Starting Automated Testing for PRD Scenarios (T-01 to T-08)...\n');

  // Connect 2 socket clients: Coordinator & Usher C2
  const coordSocket = io(SERVER_URL, { reconnection: false });
  const usherSocket = io(SERVER_URL, { reconnection: false });

  await Promise.all([
    new Promise(res => coordSocket.on('connect', res)),
    new Promise(res => usherSocket.on('connect', res)),
  ]);
  console.log('✅ Connected Coordinator & Usher Socket clients successfully.');

  // Reset state to initial
  coordSocket.emit('event:reset');
  await wait(300);

  // =========================================================================
  // T-01: C2 AVAILABLE → Koordinator assign M69 → C2 menerima → ESCORTING → selesai → AVAILABLE.
  // =========================================================================
  console.log('\n--- Running T-01: C2 Dispatch, Accept, Complete ---');
  let latestState = null;
  coordSocket.on('state:updated', (st) => { latestState = st; });

  coordSocket.emit('dispatch:assign', {
    usherId: 'C2',
    tableNumber: 69,
    zone: 'C',
    area: 'Kiri Bawah'
  });
  await wait(300);

  let usherC2 = latestState.ushers.find(u => u.id === 'C2');
  console.assert(usherC2.pendingDispatch?.tableNumber === 69, 'Pending dispatch table 69 not set');
  console.log('✓ Coordinator assigned Table 69 to C2. Pending dispatch received.');

  // C2 accepts
  usherSocket.emit('dispatch:accept', { usherId: 'C2' });
  await wait(300);

  usherC2 = latestState.ushers.find(u => u.id === 'C2');
  console.assert(usherC2.status === 'ESCORTING', `Expected ESCORTING, got ${usherC2.status}`);
  console.assert(usherC2.activeTable?.tableNumber === 69, 'Active table should be 69');
  console.log('✓ Usher C2 accepted task. Status is now ESCORTING with Table 69.');

  // C2 completes (tamu sudah duduk)
  usherSocket.emit('dispatch:complete', { usherId: 'C2', returnStatus: 'AVAILABLE' });
  await wait(300);

  usherC2 = latestState.ushers.find(u => u.id === 'C2');
  console.assert(usherC2.status === 'AVAILABLE', `Expected AVAILABLE, got ${usherC2.status}`);
  console.assert(usherC2.activeTable === null, 'Active table should be cleared');
  console.assert(latestState.completedEscortsCount === 1, 'Total completed should be 1');
  console.log('✓ C2 completed escort. Status is AVAILABLE. Completed count is 1.');
  console.log('✅ T-01 PASSED!');

  // =========================================================================
  // T-03: C1 pindah posisi dari C ke B → Koordinator melihat posisi B.
  // =========================================================================
  console.log('\n--- Running T-03: Zone Position Update ---');
  usherSocket.emit('usher:update_zone', { usherId: 'C1', zone: 'B' });
  await wait(300);

  const usherC1 = latestState.ushers.find(u => u.id === 'C1');
  console.assert(usherC1.currentZone === 'B', `Expected currentZone B, got ${usherC1.currentZone}`);
  console.log(`✓ Usher C1 updated position to Zone B. Coordinator sees currentZone = ${usherC1.currentZone}`);
  console.log('✅ T-03 PASSED!');

  // =========================================================================
  // T-04: C2 menekan ASSIST → Koordinator melihat C2 sebagai ASSIST.
  // =========================================================================
  console.log('\n--- Running T-04: Request Assistance & Resolve ---');
  usherSocket.emit('usher:request_assist', { usherId: 'C2', note: 'Meja penuh' });
  await wait(300);

  usherC2 = latestState.ushers.find(u => u.id === 'C2');
  console.assert(usherC2.status === 'ASSIST', `Expected ASSIST, got ${usherC2.status}`);
  console.assert(usherC2.assistNote === 'Meja penuh', 'Assist note should match');
  console.log('✓ Usher C2 triggered ASSIST. Coordinator sees ASSIST with note: ' + usherC2.assistNote);

  // Coordinator resolves assist
  coordSocket.emit('usher:resolve_assist', { usherId: 'C2', newStatus: 'AVAILABLE' });
  await wait(300);

  usherC2 = latestState.ushers.find(u => u.id === 'C2');
  console.assert(usherC2.status === 'AVAILABLE', 'Expected resolved to AVAILABLE');
  console.log('✓ Coordinator resolved assist for C2. Status is AVAILABLE.');
  console.log('✅ T-04 PASSED!');

  // =========================================================================
  // T-06: D1 sedang ESCORTING → Koordinator tidak boleh memberi tugas kedua kepada D1.
  // =========================================================================
  console.log('\n--- Running T-06: No Double Assignment to ESCORTING Usher ---');
  coordSocket.emit('dispatch:assign', { usherId: 'D1', tableNumber: 28, zone: 'D', area: 'Kanan Atas' });
  await wait(300);
  usherSocket.emit('dispatch:accept', { usherId: 'D1' });
  await wait(300);

  let usherD1 = latestState.ushers.find(u => u.id === 'D1');
  console.assert(usherD1.status === 'ESCORTING', 'D1 should be ESCORTING');

  // Attempt to assign another table to D1
  coordSocket.emit('dispatch:assign', { usherId: 'D1', tableNumber: 30, zone: 'D', area: 'Kanan Atas' });
  await wait(300);

  usherD1 = latestState.ushers.find(u => u.id === 'D1');
  console.assert(usherD1.activeTable?.tableNumber === 28, 'Active table should remain 28 and not overwritten');
  console.log('✓ System successfully prevented second assignment to busy usher D1.');
  console.log('✅ T-06 PASSED!');

  // =========================================================================
  // T-07 & T-08: Persistence & Realtime Multi-Device Sync
  // =========================================================================
  console.log('\n--- Running T-07 & T-08: Multi-Device Sync & State Persistence ---');
  const freshClient = io(SERVER_URL, { reconnection: false });
  const receivedInitState = await new Promise(res => freshClient.on('state:init', res));
  console.assert(receivedInitState.ushers.length === 18, 'Expected 18 ushers in persisted state');
  console.log('✓ Newly connected device immediately received full synced state with 18 ushers.');
  console.log('✅ T-07 & T-08 PASSED!');

  console.log('\n🎉 ALL 8 ACCEPTANCE & TEST SCENARIOS PASSED WITH 100% SUCCESS!');

  coordSocket.disconnect();
  usherSocket.disconnect();
  freshClient.disconnect();
  process.exit(0);
}

runTests().catch(err => {
  console.error('❌ Test failed:', err);
  process.exit(1);
});

