const localtunnel = require('localtunnel');
const http = require('http');
const https = require('https');

const PORT = process.env.PORT || 3000;

function getPublicIp() {
  return new Promise((resolve) => {
    https.get('https://api.ipify.org', (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(data.trim()));
    }).on('error', () => resolve(''));
  });
}

(async () => {
  console.log('🌐 Membuka akses publik internet untuk Jaringan Seluler (4G/5G)...');
  try {
    const publicIp = await getPublicIp();
    const tunnel = await localtunnel({ port: PORT });

    console.log('\n=================================================================');
    console.log('🎉 LINK AKSES PUBLIK (BISA DIBUKA PAKAI PAKET DATA SELULER 4G/5G):');
    console.log(`🔗 Link Aplikasi : ${tunnel.url}`);
    if (publicIp) {
      console.log(`🔑 Password IP   : ${publicIp} (Hanya jika muncul layar konfirmasi Localtunnel)`);
    }
    console.log('=================================================================\n');
    console.log('📱 Langkah untuk Usher:');
    console.log('1. Kirim link di atas ke WhatsApp Usher.');
    console.log('2. Usher klik link, pilih kode Usher mereka (misal: C2).');
    console.log('3. Aplikasi siap digunakan secara realtime di jaringan seluler 4G/5G!\n');
    console.log('Tekan Ctrl + C di terminal ini jika acara sudah selesai.');

    tunnel.on('close', () => {
      console.log('Tunnel ditutup.');
    });
  } catch (err) {
    console.error('Gagal membuat tunnel:', err);
  }
})();
